import { test, expect } from '@playwright/test';

test.describe('Table Row Numbers', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the page containing the table
    await page.goto('/');
    // Wait for the table to be visible
    await page.waitForSelector('table');
  });

  test('should display row numbers in the first column', async ({ page }) => {
    // Get all rows in the table body
    const tableRows = await page.locator('tbody tr').all();

    // Verify that there are rows in the table
    expect(tableRows.length).toBeGreaterThan(0);

    // Check each row has a row number in the first column
    for (let i = 0; i < tableRows.length; i++) {
      const firstCell = tableRows[i].locator('td').first();
      const cellText = await firstCell.textContent();

      // Row numbers should be 1-indexed
      expect(cellText?.trim()).toBe((i + 1).toString());
    }
  });

  test('should have row numbers starting from 1', async ({ page }) => {
    // Get the first row's first cell
    const firstRowFirstCell = page.locator('tbody tr').first().locator('td').first();
    const firstRowNumber = await firstRowFirstCell.textContent();

    // Verify the first row number is 1
    expect(firstRowNumber?.trim()).toBe('1');

    // Get the second row's first cell
    const secondRowFirstCell = page.locator('tbody tr').nth(1).locator('td').first();
    const secondRowNumber = await secondRowFirstCell.textContent();

    // Verify the second row number is 2
    expect(secondRowNumber?.trim()).toBe('2');
  });

  test('should have row numbers in sequential order', async ({ page }) => {
    // Get all first cells (row numbers) from the table
    const rowNumberCells = await page.locator('tbody tr td:first-child').all();

    // Verify sequential numbering
    for (let i = 0; i < rowNumberCells.length; i++) {
      const cellText = await rowNumberCells[i].textContent();
      const expectedNumber = i + 1;
      expect(cellText?.trim()).toBe(expectedNumber.toString());
    }
  });

  test('should align row numbers to the left in the first column', async ({ page }) => {
    // Get the first row number cell
    const firstRowNumberCell = page.locator('tbody tr').first().locator('td').first();

    // Check that the cell has proper styling (left-aligned)
    const computedStyle = await firstRowNumberCell.evaluate((element) => {
      return window.getComputedStyle(element).textAlign;
    });

    // Row numbers should be left-aligned or inherit left alignment
    expect(['left', 'start', '']).toContain(computedStyle);
  });

  test('should maintain row numbers when table is sorted or filtered', async ({ page }) => {
    // Get initial row numbers
    const initialRowNumbers = await page.locator('tbody tr td:first-child').allTextContents();

    // Verify initial row numbers are sequential
    for (let i = 0; i < initialRowNumbers.length; i++) {
      expect(initialRowNumbers[i].trim()).toBe((i + 1).toString());
    }

    // If there's a sort button, click it to verify row numbers update
    const sortButton = page.getByRole('button', { name: /sort/i }).first();
    if (await sortButton.isVisible()) {
      await sortButton.click();
      await page.waitForTimeout(500); // Wait for sort animation

      // Verify row numbers are still sequential after sorting
      const updatedRowNumbers = await page.locator('tbody tr td:first-child').allTextContents();
      for (let i = 0; i < updatedRowNumbers.length; i++) {
        expect(updatedRowNumbers[i].trim()).toBe((i + 1).toString());
      }
    }
  });
});
